<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50 pb-safe">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 pt-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'Home' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali ke Home"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 flex-1 truncate font-medium text-ui-ink-gray-900"
					>Konfirmasi Pencairan</span
				>
				<button
					type="button"
					class="relative flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-ink-gray-600 transition-colors hover:bg-ui-surface-gray-100 hover:text-ui-ink-gray-900 active:bg-ui-surface-gray-200"
					:class="jumlahSaringan ? 'text-primary' : ''"
					title="Saring"
					aria-label="Saring"
					@click="openFilter"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-5 w-5"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="M22 3H2l8 9.46V19l4 2v-8.54L22 3z" />
					</svg>
					<span
						v-if="jumlahSaringan"
						class="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[10px] font-bold leading-none text-ui-onPrimary"
						>{{ jumlahSaringan }}</span
					>
				</button>
			</div>

			<!-- Tab kategori: H+ dihitung hari kerja Senin–Sabtu. -->
			<div class="-mx-1 mt-3 flex gap-1 overflow-x-auto">
				<button
					v-for="k in KATEGORI"
					:key="k.nilai"
					type="button"
					class="flex shrink-0 items-center gap-1.5 border-b-2 px-3 pb-2.5 pt-1 text-sm font-medium transition-colors"
					:class="
						tab === k.nilai
							? 'border-primary text-primary'
							: 'border-transparent text-ui-ink-gray-500 hover:text-ui-ink-gray-800'
					"
					@click="pilihTab(k.nilai)"
				>
					{{ k.label }}
					<span
						class="rounded-full px-1.5 py-0.5 text-[11px] font-semibold leading-none"
						:class="
							tab === k.nilai
								? 'bg-primary/10 text-primary'
								: 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
						"
						>{{ jumlah[k.nilai] || 0 }}</span
					>
				</button>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<div class="app-container-narrow flex-1 px-4 py-4 md:px-6">
			<p class="mb-3 text-xs text-ui-ink-gray-500">{{ keteranganTab }}</p>

			<pre v-if="error" class="whitespace-pre-wrap py-4 text-sm text-ui-ink-red-600">{{
				error
			}}</pre>

			<p v-else-if="loading && !rows.length" class="py-6 text-sm text-ui-ink-gray-500">
				Loading...
			</p>

			<p v-else-if="!rows.length" class="py-10 text-center text-sm text-ui-ink-gray-400">
				Tidak ada nasabah di {{ tab }}.
			</p>

			<div v-else class="space-y-2.5">
				<button
					v-for="row in rows"
					:key="row.name"
					type="button"
					class="w-full rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 text-left shadow-sm transition hover:bg-ui-surface-gray-50 active:bg-ui-surface-gray-100"
					@click="buka(row.name)"
				>
					<div class="flex items-start gap-2">
						<span class="min-w-0 flex-1">
							<span
								class="block truncate text-base font-semibold text-ui-ink-gray-900"
								>{{ row.nama_nasabah || row.name }}</span
							>
							<span class="block truncate text-sm text-ui-ink-gray-500">{{
								[row.name, row.cabang].filter(Boolean).join(' · ')
							}}</span>
						</span>
						<span
							class="shrink-0 rounded-full px-2.5 py-0.5 text-xs font-medium"
							:class="warnaStatus(row.status)"
							>{{ row.status || '—' }}</span
						>
					</div>

					<div
						class="mt-2.5 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-ui-ink-gray-500"
					>
						<span>Cair {{ tgl(row.tanggal_pencairan) }}</span>
						<span class="font-medium text-ui-ink-gray-700"
							>H+{{ row.hari_ke || 0 }}</span
						>
						<span v-if="row.nama_marketing" class="truncate"
							>CMO {{ row.nama_marketing }}</span
						>
						<span
							v-if="row.perlu_tindak_lanjut"
							class="rounded-full bg-ui-surface-amber-100 px-2 py-0.5 font-medium text-ui-ink-amber-700"
							>Perlu tindak lanjut</span
						>
					</div>
				</button>

				<button
					v-if="hasMore"
					type="button"
					class="w-full rounded-xl border border-ui-line-gray-200 bg-ui-surface py-3 text-base font-medium text-ui-action transition hover:bg-ui-surface-blue-50 disabled:opacity-60"
					:disabled="loading"
					@click="loadMore"
				>
					{{ loading ? 'Memuat…' : 'Muat lebih banyak' }}
				</button>
			</div>
		</div>

		<!-- ====== Bottom-sheet SARING ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="showFilter"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="showFilter = false"
				>
					<div
						class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl"
					>
						<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300" />
						<h2 class="mb-5 text-center text-base font-semibold text-ui-ink-gray-900">
							Filter Konfirmasi Pencairan
						</h2>

						<div class="max-h-[60vh] space-y-4 overflow-y-auto px-0.5 pb-1">
							<label class="kp-field focus-within:border-primary">
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="kp-field-ic"
									fill="none"
									stroke="currentColor"
									stroke-width="1.8"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<circle cx="11" cy="11" r="8" />
									<path d="m21 21-4.3-4.3" />
								</svg>
								<input
									v-model="draft.cari"
									type="text"
									placeholder="Nama nasabah, no perjanjian, atau nopol"
									class="kp-field-input text-xs"
								/>
							</label>

							<div v-for="p in PILIHAN" :key="p.key">
								<p class="mb-2 text-xs font-semibold text-ui-ink-gray-700">
									{{ p.label }}
								</p>
								<p v-if="!opsi[p.key].length" class="text-xs text-ui-ink-gray-400">
									Tidak ada pilihan.
								</p>
								<div class="flex flex-wrap gap-2">
									<button
										v-for="opt in opsi[p.key]"
										:key="opt"
										type="button"
										class="rounded-full border px-3 py-1.5 text-xs font-medium transition"
										:class="
											draft[p.key].includes(opt)
												? 'border-primary bg-primary/10 text-primary'
												: 'border-ui-line-gray-300 text-ui-ink-gray-700'
										"
										@click="pilihGanda(draft[p.key], opt)"
									>
										{{ opt }}
									</button>
								</div>
							</div>
						</div>

						<div class="mt-5 flex items-center gap-3">
							<button
								type="button"
								class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
								@click="clearFilter"
							>
								Bersihkan
							</button>
							<button
								type="button"
								class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
								@click="applyFilter"
							>
								Terapkan
							</button>
						</div>
					</div>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
/**
 * Konfirmasi Pencairan (CSDM) — daftar baca saja untuk CMO, Pimcab, Direktur,
 * dan Audit. Lingkup data ditegakkan server (juragan/api/portal/csdm.py):
 * CMO melihat nasabah miliknya, Pimcab mulai Kategori 2, Direktur/Audit
 * Kategori 3. Petugas CS bekerja di Desk (Meja Kerja CSDM), bukan di sini.
 *
 * Pemberitahuan lonceng membuka halaman ini dengan ?kategori=Kategori%202/3.
 */
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { useListPersistence } from '../composables/useListPersistence'

const PER_HALAMAN = 20
const KATEGORI = [
	{ nilai: 'Kategori 1', label: 'Kategori 1', ket: 'H+1 s.d. H+2 — ditangani CS & CMO.' },
	{ nilai: 'Kategori 2', label: 'Kategori 2', ket: 'H+3 s.d. H+6 — CS dibantu Pimcab.' },
	{ nilai: 'Kategori 3', label: 'Kategori 3', ket: 'H+7 ke atas — dipantau Direktur & Audit.' },
]
const PILIHAN = [
	{ key: 'status', label: 'Status' },
	{ key: 'cabang', label: 'Cabang' },
]
const WARNA = {
	'Belum Dihubungi': 'bg-ui-surface-gray-100 text-ui-ink-gray-600',
	'Dalam Proses': 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	Terkonfirmasi: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	'Gagal Dihubungi': 'bg-ui-surface-red-100 text-ui-ink-red-700',
}

const route = useRoute()
const router = useRouter()
const listPersistence = useListPersistence('KonfirmasiPencairan')
const tersimpan = listPersistence.readSession({})

function warnaStatus(s) {
	return WARNA[s] || 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
}
function tgl(v) {
	const m = String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : '—'
}
function buka(name) {
	router.push({ name: 'KonfirmasiPencairanDetail', params: { name } })
}

// ---- Tab kategori -----------------------------------------------------------
const kategoriValid = (k) => KATEGORI.some((x) => x.nilai === k)
// Urutan prioritas: tautan pemberitahuan → tab terakhir dibuka → tab pertama berisi data.
const tabDariTautan = kategoriValid(route.query.kategori) ? route.query.kategori : ''
const tab = ref(tabDariTautan || (kategoriValid(tersimpan.tab) ? tersimpan.tab : ''))
const keteranganTab = computed(() => KATEGORI.find((k) => k.nilai === tab.value)?.ket || '')

function pilihTab(k) {
	if (tab.value === k) return
	tab.value = k
	simpan()
	reload()
}

// ---- Saring -----------------------------------------------------------------
const kosongkan = () => ({ cari: '', status: [], cabang: [] })
const salin = (d) => ({ cari: d.cari, status: [...d.status], cabang: [...d.cabang] })
const terpakai = reactive({ ...kosongkan(), ...(tersimpan.filters || {}) })
const draft = reactive(kosongkan())
const showFilter = ref(false)
const opsi = reactive({ status: [], cabang: [] })
const jumlahSaringan = computed(
	() => (terpakai.cari ? 1 : 0) + terpakai.status.length + terpakai.cabang.length
)

function pilihGanda(arr, nilai) {
	const i = arr.indexOf(nilai)
	if (i === -1) arr.push(nilai)
	else arr.splice(i, 1)
}
function simpan() {
	listPersistence.writeSession({ filters: salin(terpakai), tab: tab.value })
}
function openFilter() {
	Object.assign(draft, salin(terpakai))
	showFilter.value = true
}
function applyFilter() {
	Object.assign(terpakai, salin({ ...draft, cari: draft.cari.trim() }))
	simpan()
	showFilter.value = false
	reload()
}
function clearFilter() {
	Object.assign(draft, kosongkan())
	Object.assign(terpakai, kosongkan())
	simpan()
	showFilter.value = false
	reload()
}
// Kunci kosong tidak dikirim — nilai undefined ter-serialisasi jadi "undefined".
function filtersParam() {
	const f = {}
	if (terpakai.cari) f.cari = terpakai.cari
	if (terpakai.status.length) f.status = terpakai.status
	if (terpakai.cabang.length) f.cabang = terpakai.cabang
	return JSON.stringify(f)
}

createResource({
	url: 'juragan.api.portal.csdm.get_konfirmasi_opsi',
	auto: true,
	onSuccess(d) {
		opsi.status = d?.status || []
		opsi.cabang = d?.cabang || []
	},
})

// ---- Data & pagination -----------------------------------------------------
const rows = ref([])
const jumlah = ref({})
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

const jumlahRes = createResource({
	url: 'juragan.api.portal.csdm.get_jumlah_per_kategori',
	auto: false,
	makeParams: () => ({ filters: filtersParam() }),
	onSuccess(d) {
		jumlah.value = d || {}
	},
})

const list = createResource({
	url: 'juragan.api.portal.csdm.get_konfirmasi_list',
	auto: false,
	makeParams: () => ({
		kategori: tab.value,
		filters: filtersParam(),
		start: start.value,
		limit: PER_HALAMAN,
	}),
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	jumlahRes.fetch()
	list.fetch()
}
function loadMore() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

onMounted(async () => {
	await refreshCsrfToken()
	if (!tab.value) {
		// Belum ada tab pilihan: buka kategori pertama yang berisi nasabah.
		const d = await jumlahRes.fetch()
		tab.value = KATEGORI.find((k) => (d || {})[k.nilai])?.nilai || KATEGORI[0].nilai
	}
	simpan()
	reload()
})
</script>

<style>
.kp-field {
	@apply flex w-full items-center gap-3 rounded-2xl border border-ui-line-gray-300 px-4 py-3.5 transition;
}
.kp-field-input {
	@apply w-full border-0 bg-transparent p-0 text-ui-ink-gray-800 placeholder-ui-ink-gray-500 caret-primary outline-none focus:ring-0;
}
.kp-field-ic {
	@apply h-5 w-5 shrink-0 text-ui-ink-gray-500;
}
</style>
